+            Ok(()) => return Ok(()),
+            Err(error) if !error.is_transient() || attempt >= max_attempts => {
+                return Err(error);
+            }
+            Err(_) => {
+                sleeper.sleep_ms(config.delay_for_retry(attempt));
+            }
+        }
+    }
+}
